const char* OakTlsSession::MessageToMethodName_(mojo::Message& message) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (!is_response) {
    switch (static_cast<messages::OakTlsSession>(message.name())) {
      case messages::OakTlsSession::kStartHandshake:
            return "Receive private_ai::mojom::OakTlsSession::StartHandshake";
      case messages::OakTlsSession::kProcessHandshakeFrame:
            return "Receive private_ai::mojom::OakTlsSession::ProcessHandshakeFrame";
      case messages::OakTlsSession::kEncrypt:
            return "Receive private_ai::mojom::OakTlsSession::Encrypt";
      case messages::OakTlsSession::kDecrypt:
            return "Receive private_ai::mojom::OakTlsSession::Decrypt";
    }
  } else {
    switch (static_cast<messages::OakTlsSession>(message.name())) {
      case messages::OakTlsSession::kStartHandshake:
            return "Receive reply private_ai::mojom::OakTlsSession::StartHandshake";
      case messages::OakTlsSession::kProcessHandshakeFrame:
            return "Receive reply private_ai::mojom::OakTlsSession::ProcessHandshakeFrame";
      case messages::OakTlsSession::kEncrypt:
            return "Receive reply private_ai::mojom::OakTlsSession::Encrypt";
      case messages::OakTlsSession::kDecrypt:
            return "Receive reply private_ai::mojom::OakTlsSession::Decrypt";
    }
  }
  return "Receive unknown mojo message";
#else
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (is_response) {
    return "Receive mojo reply";
  } else {
    return "Receive mojo message";
  }
#endif // BUILDFLAG(MOJO_TRACE_ENABLED)
}

