class OakTlsSession_StartHandshake_ProxyToResponder : public ::mojo::internal::ProxyToResponder {
 public:
  static OakTlsSession::StartHandshakeCallback CreateCallback(
      ::mojo::Message& message,
      std::unique_ptr<mojo::internal::ResponderThunk>&& responder) {
    std::unique_ptr<OakTlsSession_StartHandshake_ProxyToResponder> proxy(
        new OakTlsSession_StartHandshake_ProxyToResponder(
            message, std::move(responder)));
    return base::BindOnce(&Transform)
      .Then(base::BindOnce(&OakTlsSession_StartHandshake_ProxyToResponder::Run,
                          std::move(proxy)));
  }

  static OakTlsSession_StartHandshake_ResponseParam_ResultPtr Transform(base::expected<
  TlsHandshakePtr,
  TlsHandshakeError> in) {
    return in.has_value() ? ::private_ai::mojom::OakTlsSession_StartHandshake_ResponseParam_Result::NewSuccess(std::move(in.value())) :
                            ::private_ai::mojom::OakTlsSession_StartHandshake_ResponseParam_Result::NewFailure(std::move(in.error()));
  }



  ~OakTlsSession_StartHandshake_ProxyToResponder() {
#if DCHECK_IS_ON()
    if (responder_) {
      // If we're being destroyed without being run, we want to ensure the
      // binding endpoint has been closed. This checks for that asynchronously.
      // We pass a bound generated callback to handle the response so that any
      // resulting DCHECK stack will have useful interface type information.
      // Instantiate a ScopedFizzleBlockShutdownTasks to allow this request to
      // fizzle if this happens after shutdown and the endpoint is bound to a
      // BLOCK_SHUTDOWN sequence.
      base::ThreadPoolInstance::ScopedFizzleBlockShutdownTasks fizzler;
      responder_->IsConnectedAsync(base::BindOnce(&OnIsConnectedComplete));
    }
#endif
  }

 private:
  OakTlsSession_StartHandshake_ProxyToResponder(
      ::mojo::Message& message,
      std::unique_ptr<mojo::internal::ResponderThunk>&& responder)
      : ::mojo::internal::ProxyToResponder(message, std::move(responder)) {
  }

#if DCHECK_IS_ON()
  static void OnIsConnectedComplete(bool connected) {
    DCHECK(!connected)
        << "OakTlsSession::StartHandshakeCallback was destroyed without "
        << "first either being run or its corresponding binding being closed. "
        << "It is an error to drop response callbacks which still correspond "
        << "to an open interface pipe.";
  }
#endif

  void Run(
      OakTlsSession_StartHandshake_ResponseParam_ResultPtr in_result);
};

bool OakTlsSession_StartHandshake_ForwardToCallback::Accept(
    mojo::Message* message) {
  DCHECK(message->is_serialized());
  internal::OakTlsSession_StartHandshake_ResponseParams_Data* params =
      reinterpret_cast<
          internal::OakTlsSession_StartHandshake_ResponseParams_Data*>(
              message->mutable_payload());
  

  // Validation for OakTlsSession.0
  bool success = true;
  OakTlsSession_StartHandshake_ResponseParam_ResultPtr p_result{};
  OakTlsSession_StartHandshake_ResponseParamsDataView input_data_view(params, message);
  
  if (success && !input_data_view.ReadResult(&p_result))
    success = false;
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        OakTlsSession::Name_, 0, true);
    return false;
  }
  if (!callback_.is_null()) {
    if (p_result->is_success()) {
      std::move(callback_).Run(base::ok(std::move(p_result->get_success())));
    } else {
      std::move(callback_).Run(base::unexpected(std::move(p_result->get_failure())));
    }
  }
  return true;
}

