void OakSessionAsyncWaiter::InitiateHandshake(
    ::private_ai::HandshakeMessage* out_request) {
  base::RunLoop loop;
  proxy_->InitiateHandshake(
      base::BindOnce(
          [](base::RunLoop* loop,
             ::private_ai::HandshakeMessage* out_request
,
             ::private_ai::HandshakeMessage request) {*out_request = std::move(request);
            loop->Quit();
          },
          &loop,
          out_request));
  loop.Run();
}

::private_ai::HandshakeMessage OakSessionAsyncWaiter::InitiateHandshake(
    ) {
  ::private_ai::HandshakeMessage async_wait_result;
  InitiateHandshake(&async_wait_result);
  return async_wait_result;
}

void OakSessionAsyncWaiter::CompleteHandshake(
    ::private_ai::HandshakeMessage response, bool* out_success) {
  base::RunLoop loop;
  proxy_->CompleteHandshake(
      std::move(response),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool OakSessionAsyncWaiter::CompleteHandshake(
    ::private_ai::HandshakeMessage response) {
  bool async_wait_result;
  CompleteHandshake(std::move(response),&async_wait_result);
  return async_wait_result;
}

